//! The head line of a generated file names the hash of its own body: a hand change is found whatever the blueprint says (K3 of the S2 review).
mod support;
use fs_blueprint::emit::header::{sha256_hex, untouched};
use fs_blueprint::emit::write::{write, Store};
use support::synth::{blueprint, MemStore};
use support::{generate, FakeCatalog};

const MAIN: &str = "crates/fs-beta-shelf-planner-bin/src/main.rs";

#[test]
fn the_head_line_names_the_hash_of_the_body() {
    let arts = generate(&blueprint(1), &FakeCatalog).unwrap();
    for a in arts
        .iter()
        .filter(|a| a.content.starts_with("// generated") || a.content.starts_with("# generated"))
    {
        let (head, body) = a.content.split_once('\n').unwrap();
        assert!(
            head.contains(&format!("content sha256 {}", sha256_hex(body).unwrap())),
            "{}",
            a.path
        );
        assert!(untouched(&a.content), "{}", a.path);
    }
}

#[test]
fn a_changed_body_is_not_untouched_and_neither_is_a_head_without_hash_or_a_foreign_file() {
    let arts = generate(&blueprint(1), &FakeCatalog).unwrap();
    let main = arts
        .iter()
        .find(|a| a.path == MAIN)
        .unwrap()
        .content
        .clone();
    assert!(untouched(&main));
    assert!(!untouched(&format!("{main}// hand\n")));
    assert!(!untouched(&main.replace("fn main", "fn mein")));
    assert!(!untouched(
        &main.replace("content sha256 ", "content sha257 ")
    ));
    let no_hash = main
        .lines()
        .next()
        .unwrap()
        .split("; content")
        .next()
        .unwrap()
        .to_string()
        + "; do not edit by hand\n"
        + main.split_once('\n').unwrap().1;
    assert!(!untouched(&no_hash));
    assert!(!untouched("fn main() {}\n"));
    assert!(!untouched(""));
    assert!(!untouched("// generated by fs-blueprint 0.0.14"));
}

#[test]
fn a_hand_changed_file_of_an_older_blueprint_is_refused_but_an_untouched_one_is_replaced() {
    let mut store = MemStore::default();
    write(&generate(&blueprint(1), &FakeCatalog).unwrap(), &mut store).unwrap();
    let mut other = blueprint(1);
    other.program.summary.en = Some("something else".to_string());
    let new = generate(&other, &FakeCatalog).unwrap();
    // untouched: replaced although its head names an older blueprint
    let mut fresh = MemStore {
        files: store.files.clone(),
        fail: false,
    };
    write(&new, &mut fresh).unwrap();
    assert_ne!(fresh.files[MAIN], store.files[MAIN]);
    // hand changed: refused, nothing written
    store.files.get_mut(MAIN).unwrap().push_str("// hand\n");
    let before = store.files.clone();
    let err = write(&new, &mut store).unwrap_err();
    assert_eq!(
        err.iter().map(ToString::to_string).collect::<Vec<_>>(),
        [format!("generated-changed{{path={MAIN}}}")]
    );
    assert_eq!(store.files, before);
    let _ = store.read(MAIN);
}
